        }
        pub fn @"c"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"swap", 3, "ir.Swap.c");
        }
        pub fn @"d"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"swap", 4, "ir.Swap.d");
        }
    };
    pub const Return = struct {
        pub fn @"value"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"return", 1, "ir.Return.value");
        }
    };
    pub const Yield = struct {
        pub fn @"value"(@"ir.node": @"ir.Sexp") @"ir.Sexp" {
            return @"ir.at"(@"ir.node", .@"yield", 1, "ir.Yield.value");
        }
    };
    pub const Pass = struct {
    };
    pub const Array = struct {
        pub fn @"items"(@"ir.node": @"ir.Sexp") []const @"ir.Sexp" {
            return @"ir.restAt"(@"ir.node", .@"array", 1, "ir.Array.items");
        }
    };
    pub const Neg = struct {
