/// Slot `slot` of `node`, a node of `kind` (checked in safety builds).
fn @"ir.at"(node: Sexp, comptime kind: Tag, comptime slot: usize, comptime what: []const u8) Sexp {
    @"ir.check"(node, kind, what);
    const items = node.items();
    return if (slot < items.len) items[slot] else .nil;
}

/// The children of `node` from `slot` on.
fn @"ir.restAt"(node: Sexp, comptime kind: Tag, comptime slot: usize, comptime what: []const u8) []const Sexp {
    @"ir.check"(node, kind, what);
    const items = node.items();
    return if (slot < items.len) items[slot..] else &.{};
}

fn @"ir.check"(node: Sexp, comptime kind: Tag, comptime what: []const u8) void {
    if (@import("builtin").optimize.runtimeSafety() and !node.isKind(kind)) {
        const actual = if (node.kind()) |k| @tagName(k) else @tagName(node);
        std.debug.panic(what ++ ": node is '{s}', not '" ++ @tagName(kind) ++ "'", .{actual});
    }
}


// =============================================================================
// Grammar
// =============================================================================

/// Node spans and rule ids are recorded (`@schema` or `--spans`).
pub const nodeStore = true;
/// Element extents are kept for side-band labels and nested nodes.
const elemEnds = true;
/// Lists keep trailing nils: positions are fixed by the schema.
const keepTrailingNils = true;
const hasTrivia = true;
const hasRepair = true;
const numSymbols = 48;
const endSymbol: u16 = 1;
const errorSymbol: u16 = 2;

fn tokenToSymbol(_: *BaseParser, token: Token) u16 {
    return switch (token.cat) {
        .@"eof" => 1,
        .@"newline" => 8,
        .@"let" => 14,
        .@"ident" => 15,
        .@"if" => 17,
        .@"then" => 18,
        .@"unless" => 19,
        .@"else" => 20,
        .@"for" => 21,
        .@"ptr" => 22,
        .@"in" => 23,
        .@"do" => 24,
        .@"call" => 26,
        .@"swap" => 32,
        .@"with" => 33,
        .@"return" => 34,
        .@"yield" => 35,
        .@"integer" => 36,
        .@"pass" => 37,
        .@"eq" => 9,
        .@"colon" => 16,
        .@"comma" => 25,
        .@"lparen" => 27,
        .@"rparen" => 31,
        .@"minus" => 38,
        .@"lbracket" => 39,
        .@"rbracket" => 40,
        .@"plus" => 45,
        .@"star" => 46,
        .@"slash" => 47,
        .@"plus_eq" => 11,
        .@"minus_eq" => 12,
        .@"star_eq" => 13,
        else => 2, // error
    };
}

fn executeAction(self: *BaseParser, ruleId: u16, pass: []Sexp) Sexp {
    @setEvalBranchQuota(1_000_000);
    return switch (ruleId) {
        0 => blk: { var out: std.ArrayList(Sexp) = .empty; out.append(self.allocator(), .{ .tag = .@"module" }) catch break :blk self.oomNil(); for (pass[0].items()) |item| out.append(self.allocator(), item) catch break :blk self.oomNil(); break :blk self.finishList(&out, .tree); },
        1 => self.build(&.{ pass[0] }, .spread),
        2 => blk: { var out = self.extendList(pass[0]) catch break :blk self.oomNil(); out.append(self.allocator(), pass[2]) catch break :blk self.oomNil(); break :blk self.keepList(&out, .spread); },
        3 => pass[0],
        4 => self.build(&.{ .{ .tag = .@"set" }, .nil, pass[0], pass[2] }, .tree),
        5 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"+=" }, pass[0], pass[2] }, .tree),
        6 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"-=" }, pass[0], pass[2] }, .tree),
        7 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"*=" }, pass[0], pass[2] }, .tree),
        8 => self.build(&.{ .{ .tag = .@"set" }, .{ .tag = .@"+=" }, self.nested(self.build(&.{ .{ .tag = .@"name" }, pass[1] }, .tree), 1, 1), pass[3] }, .tree),
        9 => self.build(&.{ .{ .tag = .@"let" }, pass[1], .nil, pass[3] }, .tree),
        10 => self.build(&.{ .{ .tag = .@"let" }, pass[1], pass[3], pass[5] }, .tree),
        11 => self.build(&.{ .{ .tag = .@"if" }, pass[0], pass[1], pass[3], .nil }, .tree),
        12 => self.build(&.{ .{ .tag = .@"if" }, pass[0], pass[1], pass[3], .nil }, .tree),
        13 => self.build(&.{ .{ .tag = .@"if" }, pass[0], pass[1], pass[3], pass[5] }, .tree),
        14 => self.build(&.{ .{ .tag = .@"if" }, pass[0], pass[1], pass[3], pass[5] }, .tree),
        15 => self.build(&.{ .{ .tag = .@"for" }, .{ .tag = .@"ptr" }, pass[2], .nil, pass[4], pass[6] }, .tree),
        16 => self.build(&.{ .{ .tag = .@"for" }, .{ .tag = .@"ptr" }, pass[2], pass[4], pass[6], pass[8] }, .tree),
        17 => self.build(&.{ .{ .tag = .@"for" }, .nil, pass[1], .nil, pass[3], pass[5] }, .tree),
        18 => self.spreadList(pass[0], pass[1], .spread),
        19 => self.spreadList(pass[1], pass[2], .spread),
        20 => self.emptyList(.spread),
        21 => pass[0],
        22 => .nil,
        23 => blk: { var out: std.ArrayList(Sexp) = .empty; out.append(self.allocator(), .{ .tag = .@"call" }) catch break :blk self.oomNil(); out.append(self.allocator(), pass[1]) catch break :blk self.oomNil(); for (pass[3].items()) |item| out.append(self.allocator(), item) catch break :blk self.oomNil(); break :blk self.finishList(&out, .tree); },
        24 => self.build(&.{ .{ .tag = .@"swap" }, pass[2], pass[4], pass[8], pass[10] }, .tree),
        25 => self.build(&.{ .{ .tag = .@"return" }, .nil }, .tree),
        26 => self.build(&.{ .{ .tag = .@"return" }, pass[1] }, .tree),
        27 => self.build(&.{ .{ .tag = .@"yield" }, .nil }, .tree),
        28 => self.build(&.{ .{ .tag = .@"yield" }, pass[1] }, .tree),
        29 => self.build(&.{ .{ .tag = .@"yield" }, pass[1] }, .tree),
        30 => self.build(&.{ .{ .tag = .@"pass" } }, .tree),
        31 => self.build(&.{ .{ .tag = .@"pass" } }, .tree),
        32 => pass[0],
        33 => self.build(&.{ .{ .tag = .@"name" }, pass[0] }, .tree),
        34 => pass[0],
        35 => self.build(&.{ .{ .tag = .@"num" }, pass[0] }, .tree),
        36 => self.build(&.{ .{ .tag = .@"neg" }, self.nested(self.build(&.{ .{ .tag = .@"num" }, pass[1] }, .tree), 1, 1) }, .tree),
        37 => pass[1],
        38 => blk: { var out: std.ArrayList(Sexp) = .empty; out.append(self.allocator(), .{ .tag = .@"array" }) catch break :blk self.oomNil(); for (pass[1].items()) |item| out.append(self.allocator(), item) catch break :blk self.oomNil(); break :blk self.finishList(&out, .tree); },
        40 => self.build(&.{ .{ .tag = .@"+" }, pass[0], pass[2] }, .tree),
        41 => self.build(&.{ .{ .tag = .@"-" }, pass[0], pass[2] }, .tree),
        42 => pass[0],
        43 => self.build(&.{ .{ .tag = .@"*" }, pass[0], pass[2] }, .tree),
        44 => self.build(&.{ .{ .tag = .@"/" }, pass[0], pass[2] }, .tree),
        45 => pass[0],
        46 => pass[0],
        else => unreachable,
    };
}

