/// The `@repair` class of a grammar symbol.
fn repairClass(sym: u16) RepairClass {
    return switch (sym) {
        15 => .hole,
        8 => .terminator,
        else => .none,
    };
}

fn ruleSideLabels(rule: u16) []const SideLabel {
    return switch (rule) {
        4 => &.{ .{ .role = .@"eq", .pass = 1 }, },
        else => &.{},
    };
}

// =============================================================================
// Schema slots
// =============================================================================

/// Slot of `role` in nodes of `kind` (the head is slot 0).
fn slotOf(kind: Tag, role: Role) ?usize {
    return switch (kind) {
        .@"set" => switch (role) {
            .@"op" => 1,
            .@"target" => 2,
            .@"value" => 3,
            else => null,
        },
        .@"let" => switch (role) {
            .@"name" => 1,
            .@"type" => 2,
            .@"value" => 3,
            else => null,
        },
        .@"if" => switch (role) {
            .@"kw" => 1,
            .@"cond" => 2,
            .@"then" => 3,
            .@"else" => 4,
            else => null,
        },
        .@"for" => switch (role) {
            .@"mode" => 1,
            .@"var" => 2,
            .@"index" => 3,
            .@"iter" => 4,
            .@"body" => 5,
            else => null,
        },
        .@"call" => switch (role) {
            .@"callee" => 1,
            else => null,
        },
        .@"swap" => switch (role) {
            .@"a" => 1,
            .@"b" => 2,
            .@"c" => 3,
            .@"d" => 4,
            else => null,
        },
        .@"return" => switch (role) {
            .@"value" => 1,
            else => null,
        },
        .@"yield" => switch (role) {
            .@"value" => 1,
            else => null,
        },
        .@"neg" => switch (role) {
            .@"value" => 1,
            else => null,
        },
        .@"num" => switch (role) {
            .@"value" => 1,
            else => null,
        },
        .@"name" => switch (role) {
            .@"id" => 1,
            else => null,
        },
        .@"+" => switch (role) {
            .@"left" => 1,
            .@"right" => 2,
            else => null,
        },
        .@"-" => switch (role) {
            .@"left" => 1,
            .@"right" => 2,
            else => null,
        },
        .@"*" => switch (role) {
            .@"left" => 1,
            .@"right" => 2,
            else => null,
        },
        .@"/" => switch (role) {
            .@"left" => 1,
            .@"right" => 2,
            else => null,
        },
        .@"note" => switch (role) {
            .@"text" => 1,
            else => null,
        },
        else => null,
    };
}

/// First slot of rest role `role` in nodes of `kind`.
fn restSlotOf(kind: Tag, role: Role) ?usize {
    return switch (kind) {
        .@"module" => if (role == .@"stmts") 1 else null,
        .@"call" => if (role == .@"args") 2 else null,
        .@"array" => if (role == .@"items") 1 else null,
        else => null,
    };
}

/// The slot role at `slot` of nodes of `kind`.
fn roleAt(kind: Tag, slot: usize) ?Role {
    return switch (kind) {
        .@"set" => switch (slot) {
            1 => .@"op",
            2 => .@"target",
            3 => .@"value",
            else => null,
        },
        .@"let" => switch (slot) {
            1 => .@"name",
            2 => .@"type",
            3 => .@"value",
            else => null,
        },
        .@"if" => switch (slot) {
            1 => .@"kw",
            2 => .@"cond",
            3 => .@"then",
            4 => .@"else",
            else => null,
        },
        .@"for" => switch (slot) {
            1 => .@"mode",
            2 => .@"var",
            3 => .@"index",
            4 => .@"iter",
            5 => .@"body",
            else => null,
        },
        .@"call" => switch (slot) {
            1 => .@"callee",
            else => null,
        },
        .@"swap" => switch (slot) {
            1 => .@"a",
            2 => .@"b",
            3 => .@"c",
            4 => .@"d",
            else => null,
        },
        .@"return" => switch (slot) {
            1 => .@"value",
            else => null,
        },
        .@"yield" => switch (slot) {
            1 => .@"value",
            else => null,
        },
        .@"neg" => switch (slot) {
            1 => .@"value",
            else => null,
        },
        .@"num" => switch (slot) {
            1 => .@"value",
            else => null,
        },
        .@"name" => switch (slot) {
            1 => .@"id",
            else => null,
        },
        .@"+" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"-" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"*" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"/" => switch (slot) {
            1 => .@"left",
            2 => .@"right",
            else => null,
        },
        .@"note" => switch (slot) {
            1 => .@"text",
            else => null,
        },
        else => null,
    };
}

fn restRoleOf(kind: Tag) ?struct { role: Role, slot: usize } {
    return switch (kind) {
        .@"module" => .{ .role = .@"stmts", .slot = 1 },
        .@"call" => .{ .role = .@"args", .slot = 2 },
        .@"array" => .{ .role = .@"items", .slot = 1 },
        else => null,
    };
}

// =============================================================================
// API
// =============================================================================

pub const Parser = if (@hasDecl(lang, "Parser")) lang.Parser else BaseParser;

/// Parse a whole program with a new `Parser`. The caller owns
/// `result.parser` and must `deinit()` it when done with the tree.
pub fn parseProgram(allocator: std.mem.Allocator, source: []const u8) !struct { parser: Parser, sexp: Sexp } {
    var p = Parser.init(allocator, source);
    errdefer p.deinit();
    const sexp = try p.parseProgram();
    return .{ .parser = p, .sexp = sexp };
}
